internal class PolygonRevealData private constructor(
    val yellowArtwork: Bitmap,
    val regionPath: Path,
    val strokes: List<LessonStroke>,
    val coordinateWidth: Float,
    val coordinateHeight: Float,
    val connections: List<LessonConnection>
